"""
Zscaler Cleanup Strategy Generator (Self-Contained)
------------------------------------------------------
Generates both cleanup strategy Excel workbooks with all
data and analysis embedded. No external files needed.

PowerShell:
    pip install openpyxl
    python zscaler_cleanup_generator.py

Output (in current directory):
    - Zscaler_URL_Filtering_Cleanup_Strategy.xlsx
    - Zscaler_SSL_Inspection_Cleanup_Strategy.xlsx
"""

import json, zlib, base64, os, sys

try:
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
except ImportError:
    print("ERROR: openpyxl required. Install: pip install openpyxl")
    sys.exit(1)

_DATA = """"""

_STYLES = """"""


def _load_data():
    return json.loads(zlib.decompress(base64.b64decode(_DATA)))

def _load_styles():
    return json.loads(zlib.decompress(base64.b64decode(_STYLES)))

# Styling constants
URL_H_FILL = PatternFill("solid", fgColor="4472C4")
URL_H_FONT = Font(name="Calibri", bold=True, size=11, color="FFFFFF")
URL_NORM = Font(name="Calibri", size=11)
URL_TITLE = Font(name="Calibri", bold=True, size=14, color="1F4E79")
URL_BDR = Border(left=Side(style="thin", color="B4B4B4"), right=Side(style="thin", color="B4B4B4"),
                 top=Side(style="thin", color="B4B4B4"), bottom=Side(style="thin", color="B4B4B4"))

SSL_H_FILL = PatternFill("solid", fgColor="404040")
SSL_H_FONT = Font(name="Arial", bold=True, size=10, color="FFFFFF")
SSL_NORM = Font(name="Arial", size=10)
SSL_TITLE = Font(name="Arial", bold=True, size=13)
SSL_BDR = Border(left=Side(style="thin", color="AAAAAA"), right=Side(style="thin", color="AAAAAA"),
                 top=Side(style="thin", color="AAAAAA"), bottom=Side(style="thin", color="AAAAAA"))

FILLS = {}
for c in ["FFC7CE","FFFFCC","C6EFCE","D6E4F0","FCE4D6","F2DCDB","FDE9D9","D8E4BC","FFFF00"]:
    FILLS["FF"+c] = PatternFill("solid", fgColor=c)
FILLS["FF4472C4"] = PatternFill("solid", fgColor="4472C4")
FILLS["FF404040"] = PatternFill("solid", fgColor="404040")


def build_wb(sheets_data, sheets_meta, sheets_styles, wb_type):
    wb = Workbook()
    if wb_type == "url":
        hf, hfn, nf, tf, bdr = URL_H_FILL, URL_H_FONT, URL_NORM, URL_TITLE, URL_BDR
    else:
        hf, hfn, nf, tf, bdr = SSL_H_FILL, SSL_H_FONT, SSL_NORM, SSL_TITLE, SSL_BDR

    first = True
    for sname, rows in sheets_data.items():
        ws = wb.active if first else wb.create_sheet(sname)
        if first:
            ws.title = sname
            first = False

        meta = sheets_meta.get(sname, {})
        ss = sheets_styles.get(sname, {})

        for ri, row in enumerate(rows, 1):
            is_hdr = False
            key1 = f"{ri},1"
            if key1 in ss:
                fc = ss[key1].get("font_color", "")
                if fc in ("00FFFFFF", "FFFFFFFF"):
                    is_hdr = True
            for ci, val in enumerate(row, 1):
                if val is None: continue
                cell = ws.cell(row=ri, column=ci, value=val)
                key = f"{ri},{ci}"
                if is_hdr:
                    cell.font = hfn; cell.fill = hf
                elif ri == 1 and ci == 1 and isinstance(val, str) and len(val) > 20:
                    cell.font = tf
                else:
                    if key in ss:
                        fr = ss[key].get("fill", "")
                        if fr in FILLS and fr not in ("FF4472C4", "FF404040"):
                            cell.fill = FILLS[fr]
                        fc = ss[key].get("font_color", "")
                        if fc and fc.startswith("FF") and fc != "FF000000":
                            cell.font = Font(name=nf.name, size=nf.size, color=fc[2:])
                        else:
                            cell.font = nf
                    else:
                        cell.font = nf
                cell.border = bdr
                cell.alignment = Alignment(wrap_text=True, vertical="top")

        for cs, w in meta.get("col_widths", {}).items():
            ws.column_dimensions[get_column_letter(int(cs))].width = w
        for rs, h in meta.get("row_heights", {}).items():
            ws.row_dimensions[int(rs)].height = h
        for mr in meta.get("merges", []):
            try: ws.merge_cells(mr)
            except: pass
        if meta.get("freeze"): ws.freeze_panes = meta["freeze"]
        if meta.get("autofilter"): ws.auto_filter.ref = meta["autofilter"]

    return wb


def main():
    print("Loading embedded data...")
    p = _load_data()
    s = _load_styles()
    d = os.getcwd()

    print("Building URL Filtering Cleanup Strategy...")
    wb1 = build_wb(p["url"]["data"], p["url"]["meta"], s["url"], "url")
    f1 = os.path.join(d, "Zscaler_URL_Filtering_Cleanup_Strategy.xlsx")
    wb1.save(f1)
    print(f"  Saved: {f1}")

    print("Building SSL Inspection Cleanup Strategy...")
    wb2 = build_wb(p["ssl"]["data"], p["ssl"]["meta"], s["ssl"], "ssl")
    f2 = os.path.join(d, "Zscaler_SSL_Inspection_Cleanup_Strategy.xlsx")
    wb2.save(f2)
    print(f"  Saved: {f2}")

    print("\nDone!")

if __name__ == "__main__":
    main()
